/**
 * Writes the solved themes out to every target in `generated/`: CSS, TS,
 * JSON, QML, OpenTUI and ANSI.
 *
 * @module
 */
import { toCss, toHex } from "./color.ts";
import {
  MonoFont,
  type BorderStrength,
  type Density,
  type Style,
} from "./schema.ts";
import {
  check,
  modes,
  statuses,
  type Check,
  type Mode,
  type ResolvedTheme,
  type Roles,
} from "./solve.ts";

/**
 * The note at the top of every file Groundwork writes for its own themes.
 * Each writer takes another, as `build` passes for an app's.
 */
export const header =
  "Generated by `mise run gen` from packages/tokens. Don't edit.";

/**
 * The cascade layers Groundwork's CSS sits in: the tokens and themes, then
 * the elements' document styles. CSS a page writes outside a layer wins over
 * both, whatever its specificity, so an app overrides a token or a style by
 * just setting it.
 */
export const layers = {
  tokens: "groundwork.tokens",
  components: "groundwork.components",
} as const;

/** Wraps `rules` in the cascade layer `layer`. */
export const inLayer = (layer: string, rules: string) =>
  `@layer ${layer} {\n${rules
    .split("\n")
    .map((line) => (line === "" ? line : `  ${line}`))
    .join("\n")}\n}`;

/** A family's stack, falling back to the system's sans or monospace font. */
const fontStack = (font: string, mono: boolean) => {
  if (font === "System UI") {
    return 'system-ui, -apple-system, "Segoe UI", Roboto, sans-serif';
  }

  const generic = mono ? "ui-monospace, monospace" : "system-ui, sans-serif";

  return `"${font} Variable", "${font}", ${generic}`;
};

const monoSuggestions: readonly string[] = MonoFont.literals;

const round = (value: number) => Number(value.toFixed(4));

/** The scale a density preset stands for, or the number given. */
const densityScale = (density: Density) => {
  switch (density) {
    case "compact": {
      return 0.85;
    }

    case "normal": {
      return 1;
    }

    case "roomy": {
      return 1.2;
    }

    default: {
      return density;
    }
  }
};

/**
 * How much controls grow or shrink with density, less than spacing does as
 * it grows: half as much above 1, which gives the roomy preset's 1.1.
 */
const controlScale = (density: Density) => {
  const scale = densityScale(density);

  return round(scale <= 1 ? scale : 1 + (scale - 1) / 2);
};

/** The level a border preset stands for, from 0 to 3, or the number given. */
const borderLevel = (strength: BorderStrength) => {
  switch (strength) {
    case "none": {
      return 0;
    }

    case "hairline": {
      return 1;
    }

    case "soft": {
      return 2;
    }

    case "strong": {
      return 3;
    }

    default: {
      return strength;
    }
  }
};

const borderRoles = [
  "transparent",
  "var(--gw-color-border-quiet)",
  "var(--gw-color-border-normal)",
  "var(--gw-color-border-loud)",
] as const;

/**
 * The border color for a strength: the theme's quiet, normal or loud border
 * at 1, 2 and 3, and a mix of the two either side between them.
 */
const borderColor = (strength: BorderStrength) => {
  const level = borderLevel(strength);
  const below = Math.floor(level);
  const share = round((level - below) * 100);

  if (share === 0) return borderRoles[below] ?? borderRoles[3];

  return `color-mix(in oklch, ${borderRoles[below + 1]} ${share}%, ${borderRoles[below]})`;
};

/** The style as `--gw-*` properties, so components never branch on a theme. */
const styleProperties = (style: Style) => ({
  "font-sans": fontStack(style.font, false),
  "font-figures":
    style.figures === undefined
      ? fontStack(style.font, false)
      : fontStack(
          style.figures,
          style.figuresMono ?? monoSuggestions.includes(style.figures),
        ),
  "font-mono": fontStack(style.mono, true),
  "font-weight-regular": String(style.weights.regular),
  "font-weight-strong": String(style.weights.strong),
  density: String(densityScale(style.density)),
  "control-scale": String(controlScale(style.density)),
  ...spacing,
  "radius-panel": `${style.radius.panel}px`,
  "radius-control": `${style.radius.control}px`,
  "radius-chip": `${style.radius.chip}px`,
  "border-width":
    borderLevel(style.border.strength) === 0
      ? "0px"
      : `${style.border.width}px`,
  "border-color": borderColor(style.border.strength),
  "label-transform": style.capitals ? "uppercase" : "none",
  "label-tracking": style.capitals ? "0.06em" : "normal",
  "link-color": "var(--gw-color-link)",
  "link-underline": style.link.underline === "thick" ? "2px" : "1px",
  "panel-sheen":
    style.surfaceAccent === "sheen"
      ? "linear-gradient(160deg, color-mix(in oklch, var(--gw-color-accent) 14%, transparent), transparent 55%)"
      : "none",
  "panel-marker": style.surfaceAccent === "marker" ? "4px" : "0px",
  "panel-flange": style.surfaceAccent === "flange" ? "3px" : "0px",
  "panel-flange-color":
    style.surfaceAccent === "flange"
      ? "var(--gw-color-accent)"
      : "var(--gw-border-color)",
  "row-padding":
    style.rows === "dense"
      ? "calc(var(--gw-space-1) * 1.5)"
      : "var(--gw-space-3)",
});

/** Shadows' default ink, as `r g b`, and strength in each scheme. */
const shadowDefaults = {
  light: { ink: "16 20 28", strength: 1 },
  dark: { ink: "0 0 0", strength: 3 },
};

const rgbChannels = (hex: string) =>
  [1, 3, 5].map((at) => parseInt(hex.slice(at, at + 2), 16)).join(" ");

/**
 * A mode's shadows: the theme's own ink and strength for that mode, then for
 * every mode, then the default. Darker starts from dark's, as roles do.
 */
const shadows = (style: Style, mode: Mode) => {
  const shadow = style.shadow;
  const scheme = mode === "light" ? "light" : "dark";

  const ink =
    (mode === "darker" ? shadow?.darker?.ink : undefined) ??
    shadow?.[scheme]?.ink ??
    shadow?.ink;

  const strength =
    (mode === "darker" ? shadow?.darker?.strength : undefined) ??
    shadow?.[scheme]?.strength ??
    shadow?.strength ??
    shadowDefaults[scheme].strength;

  const rgb = ink === undefined ? shadowDefaults[scheme].ink : rgbChannels(ink);

  return {
    "shadow-s": `0 1px 2px rgb(${rgb} / ${0.06 * strength})`,
    "shadow-m": `0 4px 12px rgb(${rgb} / ${0.08 * strength})`,
    "shadow-l": `0 12px 32px rgb(${rgb} / ${0.12 * strength})`,
  };
};

/**
 * Spacing scales with the theme's density. A custom property's `var()`
 * resolves where it's declared, so the scale is declared again in every
 * theme beside its density, not only on `:root`.
 */
const spacing = {
  // Home Assistant's scale: 4px steps, space-1 to space-20, plus a half step
  "space-0-5": "calc(0.125rem * var(--gw-density))",
  ...Object.fromEntries(
    Array.from({ length: 20 }, (_, index) => [
      `space-${index + 1}`,
      `calc(${(index + 1) * 0.25}rem * var(--gw-density))`,
    ]),
  ),
};

const foundations = {
  density: "1",
  "control-scale": "1",
  ...spacing,
  "font-size-multiplier": "1",
  "font-size-2xs": "calc(0.6875rem * var(--gw-font-size-multiplier))",
  "font-size-xs": "calc(0.75rem * var(--gw-font-size-multiplier))",
  "font-size-s": "calc(0.875rem * var(--gw-font-size-multiplier))",
  "font-size-m": "calc(1rem * var(--gw-font-size-multiplier))",
  "font-size-l": "calc(1.125rem * var(--gw-font-size-multiplier))",
  "font-size-xl": "calc(1.375rem * var(--gw-font-size-multiplier))",
  "font-size-2xl": "calc(1.75rem * var(--gw-font-size-multiplier))",
  "font-size-3xl": "calc(2.125rem * var(--gw-font-size-multiplier))",
  "font-size-4xl": "calc(2.5rem * var(--gw-font-size-multiplier))",
  "radius-xs": "2px",
  "radius-s": "4px",
  "radius-m": "8px",
  "radius-l": "12px",
  "radius-xl": "16px",
  "radius-pill": "999px",
  // Home Assistant's animation durations
  "motion-instant": "75ms",
  "motion-fast": "150ms",
  "motion-normal": "250ms",
  "motion-slow": "350ms",
  "motion-easing": "cubic-bezier(0.2, 0, 0, 1)",
  // How long a loading placeholder waits before it fades in, so a quick load
  // never flashes one
  "motion-delay": "500ms",
  "focus-width": "2px",
  "focus-offset": "2px",
  // The page widths: gw-page and gw-app-bar's size picks one
  "content-width": "90rem",
  "content-width-narrow": "44rem",
  "content-width-wide": "120rem",
};

const declarations = (properties: Record<string, string>, indent = "  ") =>
  Object.entries(properties)
    .map(([name, value]) => `${indent}--gw-${name}: ${value};`)
    .join("\n");

const colorProperties = (roles: Roles) =>
  Object.fromEntries(
    Object.entries(roles).map(([role, color]) => [
      `color-${role}`,
      toCss(color),
    ]),
  );

/** A mode's colors and shadows, which mode it is found from its roles. */
const modeBlock =
  (theme: ResolvedTheme) =>
  (roles: Roles, dark: boolean, indent = "  ") => {
    const mode: Mode = !dark
      ? "light"
      : roles === theme.modes.darker
        ? "darker"
        : "dark";

    return [
      `${indent}color-scheme: ${dark ? "dark" : "light"};`,
      declarations(
        { ...colorProperties(roles), ...shadows(theme.style, mode) },
        indent,
      ),
    ].join("\n");
  };

/**
 * A rule under `theme`'s selector for each of its modes, matching how
 * `data-gw-mode` and the system's scheme pick one. `block` writes a mode's
 * declarations at the indent it's given.
 */
export const modeRules = (
  theme: ResolvedTheme,
  block: (roles: Roles, dark: boolean, indent: string) => string,
) => {
  const selector = `[data-gw-theme="${theme.id}"]`;
  const { light, dark, darker } = theme.modes;
  const rules: string[] = [];

  if (light !== undefined) {
    rules.push(`${selector} {\n${block(light, false, "  ")}\n}`);
  } else if (dark !== undefined) {
    rules.push(`${selector} {\n${block(dark, true, "  ")}\n}`);
  }

  if (dark !== undefined) {
    rules.push(
      `${selector}[data-gw-mode="dark"] {\n${block(dark, true, "  ")}\n}`,
    );

    if (light !== undefined) {
      rules.push(
        `@media (prefers-color-scheme: dark) {\n  ${selector}:not([data-gw-mode]) {\n${block(dark, true, "    ")}\n  }\n}`,
      );
    }
  }

  if (darker !== undefined) {
    rules.push(
      `${selector}[data-gw-mode="darker"] {\n${block(darker, true, "  ")}\n}`,
    );
  }

  return rules;
};

const themeRules = (theme: ResolvedTheme) =>
  [
    `[data-gw-theme="${theme.id}"] {\n${declarations(styleProperties(theme.style))}\n}`,
    ...modeRules(theme, modeBlock(theme)),
  ].join("\n\n");

/**
 * One theme's `--gw-*` rules under `[data-gw-theme]`, in each of its modes,
 * in the tokens layer.
 */
export const themeCss = (theme: ResolvedTheme) =>
  inLayer(layers.tokens, themeRules(theme));

/** A control height that follows the theme's density, as the elements do. */
const dense = (rem: number) =>
  `calc(${Number(rem.toFixed(4))}rem * var(--gw-control-scale, 1))`;

/** Pre-upgrade heights for each size preset, matching `controlSizes`. */
const sized = (
  tag: string,
  rem: number,
  properties: readonly string[] = ["min-block-size"],
) =>
  Object.fromEntries(
    Object.entries({ xs: 0.6, small: 0.8, large: 1.2, xl: 1.4 }).map(
      ([size, scale]) => [
        `${tag}[size="${size}"]`,
        Object.fromEntries(
          properties.map((property) => [property, dense(rem * scale)]),
        ),
      ],
    ),
  );

/**
 * What each `gw-` element looks like before its script defines it: the
 * display and block size it will have, so nothing moves when it upgrades.
 */
const preUpgrade = {
  "gw-fade-in": { opacity: "0" },
  "gw-button, gw-menu-button, gw-segmented": {
    display: "inline-block",
    "min-block-size": dense(2.5),
    "vertical-align": "middle",
  },
  "gw-button": {
    "padding-inline": "calc(var(--gw-space-4) + 1px)",
    "font-size": "var(--gw-font-size-s)",
    "font-weight": "var(--gw-font-weight-strong)",
    "line-height": dense(2.5),
    "white-space": "nowrap",
    "text-transform": "var(--gw-label-transform)",
    "letter-spacing": "var(--gw-label-tracking)",
  },
  ...sized("gw-button", 2.5, ["min-block-size", "line-height"]),
  ...sized("gw-menu-button", 2.5),
  "gw-card": {
    display: "block",
    padding: "var(--gw-space-4)",
    border: "var(--gw-border-width) solid transparent",
  },
  "gw-card[heading]": {
    "padding-block-start":
      "calc(var(--gw-space-4) + 1.5rem + var(--gw-space-3))",
  },
  "gw-page-header": { display: "flex", "min-block-size": "3rem" },
  "gw-page-header[description]": { "min-block-size": "3.6875rem" },
  "gw-section-title": { display: "flex", "align-items": "center" },
  "gw-app-bar": {
    position: "sticky",
    "inset-block-start": "0",
    "z-index": "50",
    display: "flex",
    gap: "var(--gw-space-3)",
    "align-items": "center",
    "min-block-size": "calc(3.5rem + 1px)",
    "padding-inline":
      "max(var(--gw-space-3), (100% - var(--gw-content-width)) / 2)",
  },
  "gw-app-bar[overlay]": { position: "fixed", "inset-inline": "0" },
  // The bar's size sets the width its padding keeps the content to
  'gw-app-bar[size="narrow"]': {
    "--gw-content-width": "var(--gw-content-width-narrow)",
  },
  'gw-app-bar[size="wide"]': {
    "--gw-content-width": "var(--gw-content-width-wide)",
  },
  'gw-app-bar[size="full"]': { "--gw-content-width": "100%" },
  'gw-app-bar[reveal-after]:not(:defined) > [slot="brand"]': {
    visibility: "hidden",
  },
  "gw-theme-picker": {
    display: "inline-block",
    "min-block-size": "2.5rem",
    "vertical-align": "middle",
  },
  "gw-theme-gallery": { display: "block" },
  "gw-button[icon], gw-button[swatch]": {
    "padding-inline-start":
      "calc(var(--gw-space-4) + var(--gw-space-2) + 1.125rem + 1px)",
  },
  'gw-button:not(:defined) > [slot="icon"]': {
    "inline-size": "1.125rem",
    "block-size": "1.125rem",
    "margin-inline-end": "var(--gw-space-2)",
    "vertical-align": "middle",
  },
  "gw-chip": { display: "inline-flex", "min-block-size": dense(2) },
  ...sized("gw-chip", 2),
  "gw-badge": { display: "inline-flex", "min-block-size": dense(2.25) },
  ...sized("gw-badge", 2.25),
  "gw-dot": {
    display: "inline-block",
    "inline-size": "0.5rem",
    "min-block-size": "0.5rem",
  },
  "gw-meter": { display: "block", "min-block-size": "2.25rem" },
  "gw-gauge": {
    display: "inline-block",
    "inline-size": "8.5rem",
    "min-block-size": "9.625rem",
  },
  "gw-alert": { display: "block", "min-block-size": "2.5rem" },
  "gw-spinner, gw-skeleton-icon": {
    display: "inline-flex",
    "min-block-size": "1.25rem",
  },
  "gw-input, gw-select": {
    display: "flex",
    "min-block-size": `calc(2rem + ${dense(2.5)})`,
  },
  "gw-input:is([hint], [error]), gw-select:is([hint], [error])": {
    "min-block-size": `calc(3.75rem + ${dense(2.5)})`,
  },
  "gw-select:is([label-hidden], [inline-label])": {
    "min-block-size": dense(2.5),
  },
  "gw-select[inline-label]": { display: "inline-flex" },
  "gw-checkbox, gw-switch": { display: "flex", "min-block-size": "1.5rem" },
  "gw-stack": {
    display: "flex",
    "flex-direction": "column",
    gap: "var(--gw-space-3)",
  },
  "gw-row": {
    display: "flex",
    "flex-wrap": "wrap",
    "align-items": "center",
    gap: "var(--gw-space-2)",
  },
  "gw-grid": {
    display: "grid",
    "grid-template-columns":
      "repeat(auto-fill, minmax(min(100%, var(--gw-grid-min, 18rem)), 1fr))",
    gap: "var(--gw-space-3)",
  },
  "gw-dialog, gw-popover, gw-sheet, gw-command-menu, gw-toaster, gw-option-list":
    {
      display: "none",
    },
};

const preUpgradeCss = Object.entries(preUpgrade)
  .map(([selectors, properties]) => {
    const selector = selectors
      .split(", ")
      .map((item) =>
        item.includes(":not(:defined)") ? item : `${item}:not(:defined)`,
      )
      .join(",\n");

    const body = Object.entries(properties)
      .map(([name, value]) => `  ${name}: ${value};`)
      .join("\n");

    return `${selector} {\n${body}\n}`;
  })
  .join("\n\n");

/**
 * Small scrollbars with a rounded, quiet thumb on a clear track and no arrow
 * buttons, for the page and every element in it, at no specificity so any
 * rule of a page's wins. `--gw-scrollbar-size`, `--gw-scrollbar-thumb` and
 * `--gw-scrollbar-track` restyle them anywhere; `scrollbar-width: none` hides
 * one. Firefox, without the WebKit pseudo-elements, gets its thin scrollbar.
 */
const scrollbarCss = (scope: string) => {
  const each = (pseudo = "") => `:where(${scope})${pseudo}`;

  return `@supports not selector(::-webkit-scrollbar) {
  ${each()} {
    scrollbar-width: thin;
    scrollbar-color: ${scrollbarThumb(45)} var(--gw-scrollbar-track, transparent);
  }
}

${each("::-webkit-scrollbar")} {
  width: var(--gw-scrollbar-size, 0.4rem);
  height: var(--gw-scrollbar-size, 0.4rem);
  background: var(--gw-scrollbar-track, transparent);
}

${each("::-webkit-scrollbar-thumb")} {
  background: ${scrollbarThumb(45)};
  border-radius: ${scrollbarRadius("top", "top", "bottom", "bottom")};
}

${each("::-webkit-scrollbar-thumb:horizontal")} {
  border-radius: ${scrollbarRadius("left", "right", "right", "left")};
}

${each("::-webkit-scrollbar-thumb:hover")} {
  background: ${scrollbarThumb(70)};
}

${each("::-webkit-scrollbar-corner")} {
  background: transparent;
}`;
};

const scrollbarThumb = (strength: number) =>
  `var(--gw-scrollbar-thumb, color-mix(in oklab, var(--gw-color-text-secondary, currentColor) ${strength}%, transparent))`;

/**
 * The thumb's corners, from top left: round, or square where it meets the end
 * of its track. `--gw-scrollbar-top`, `-bottom`, `-left` and `-right` are 0 at
 * that end and 1 elsewhere.
 */
const scrollbarRadius = (...edges: readonly string[]) =>
  edges
    .map(
      (edge) =>
        `calc(var(--gw-scrollbar-size, 0.4rem) * var(--gw-scrollbar-${edge}, 1))`,
    )
    .join(" ");

/**
 * Where a scroller is against each end, for the thumb's square ends. A
 * scroller takes its own from the `gw-scrollbar-edges-y` and `-x` animations
 * on its scroll timeline; everything else resets them, so a scroller without
 * them never takes its parent's. The page's own come from the ui package,
 * since an animation on the root doesn't repaint the window's scrollbar.
 */
const scrollbarEdgesAtRules = [
  ...["top", "bottom", "left", "right"].map(
    (edge) =>
      `@property --gw-scrollbar-${edge} {\n  syntax: "<number>";\n  inherits: true;\n  initial-value: 1;\n}`,
  ),
  `@keyframes gw-scrollbar-edges-y {\n  0% {\n    --gw-scrollbar-top: 0;\n  }\n\n  1% {\n    --gw-scrollbar-top: 1;\n  }\n\n  99% {\n    --gw-scrollbar-bottom: 1;\n  }\n\n  100% {\n    --gw-scrollbar-bottom: 0;\n  }\n}`,
  `@keyframes gw-scrollbar-edges-x {\n  0% {\n    --gw-scrollbar-left: 0;\n  }\n\n  1% {\n    --gw-scrollbar-left: 1;\n  }\n\n  99% {\n    --gw-scrollbar-right: 1;\n  }\n\n  100% {\n    --gw-scrollbar-right: 0;\n  }\n}`,
].join("\n\n");

const scrollbarEdgesReset = `:where(:root *) {\n  --gw-scrollbar-top: 1;\n  --gw-scrollbar-bottom: 1;\n  --gw-scrollbar-left: 1;\n  --gw-scrollbar-right: 1;\n}`;

/**
 * Every theme's CSS. The `@property` and `@keyframes` rules stay at the top
 * level; the rest is in the tokens layer, so a page's own CSS wins. Only the
 * tokens layer is named here: the components layer is named when the
 * elements adopt their document styles, after every stylesheet on the page,
 * so a reset in an earlier layer, such as Tailwind's preflight, never wins
 * over them.
 */
export const css = (themes: readonly ResolvedTheme[], note = header) =>
  [
    `/* ${note} */`,
    scrollbarEdgesAtRules,
    inLayer(
      layers.tokens,
      [
        `:root {\n${declarations(foundations)}\n}`,
        `@media (prefers-reduced-motion: reduce) {\n  :root {\n    --gw-motion-instant: 1ms;\n    --gw-motion-fast: 1ms;\n    --gw-motion-normal: 1ms;\n    --gw-motion-slow: 1ms;\n  }\n}`,
        scrollbarCss(":root, :root *"),
        scrollbarEdgesReset,
        preUpgradeCss,
        ...themes.map(themeRules),
      ].join("\n\n"),
    ),
  ].join("\n\n") + "\n";

/** Each Blume color token and the role it takes. */
const blumeRoles = {
  background: "surface-default",
  foreground: "text-primary",
  muted: "surface-low",
  "muted-foreground": "text-secondary",
  border: "border-normal",
  accent: "accent",
  "accent-foreground": "on-accent",
  action: "fill-primary-resting",
  "action-foreground": "on-primary",
  "code-background": "surface-raised",
  "code-highlight": "fill-info-quiet",
  "code-highlight-border": "border-info",
  "code-add": "fill-success-quiet",
  "code-add-border": "border-success",
  "code-remove": "fill-danger-quiet",
  "code-remove-border": "border-danger",
  "code-error": "fill-danger-quiet",
  "code-error-border": "border-danger",
  "code-warning": "fill-warning-quiet",
  "code-warning-border": "border-warning",
  "code-word": "fill-info-quiet",
  "code-word-border": "border-info",
};

/**
 * Blume's color tokens from a theme's roles in one mode, plus the link color
 * docs-kit's `theme.css` gives prose links, as Blume has no token for it.
 */
const blumeColors = (roles: Roles) =>
  Object.fromEntries(
    [
      ...Object.entries(blumeRoles).map(
        ([token, role]) => [`--blume-${token}`, role] as const,
      ),
      ["--gw-docs-link", "link"] as const,
    ].flatMap(([property, role]) => {
      const color = roles[role];

      return color === undefined ? [] : [[property, toCss(color)]];
    }),
  );

const blumeDeclarations = (properties: Record<string, string>) =>
  Object.entries(properties)
    .map(([name, value]) => `  ${name}: ${value};`)
    .join("\n");

/**
 * A theme's Blume rules under one root selector: light on the root, dark on
 * Blume's `data-theme="dark"`, and Darker when `data-gw-darker` is set too.
 */
const blumeRules = (theme: ResolvedTheme, root: string) => {
  const { light, dark, darker } = theme.modes;

  const style = {
    "--blume-radius": `${theme.style.radius.panel}px`,
    "--blume-font-body": fontStack(theme.style.font, false),
    "--blume-font-display": fontStack(theme.style.font, false),
    "--blume-font-mono": fontStack(theme.style.mono, true),
  };

  const lightTokens: Record<string, string> =
    light === undefined ? style : { ...style, ...blumeColors(light) };

  const rules = [`${root} {\n${blumeDeclarations(lightTokens)}\n}`];

  if (dark !== undefined) {
    rules.push(
      `${root}[data-theme="dark"] {\n${blumeDeclarations(blumeColors(dark))}\n}`,
    );
  }

  if (darker !== undefined) {
    rules.push(
      `${root}[data-theme="dark"][data-gw-darker] {\n${blumeDeclarations(blumeColors(darker))}\n}`,
    );
  }

  return rules;
};

/**
 * One theme as Blume's tokens on `:root`, in each of its modes. Fonts are
 * stacks, so the site loads the files.
 */
export const blumeThemeCss = (theme: ResolvedTheme) =>
  blumeRules(theme, ":root").join("\n\n");

/** One theme's docs-kit stylesheet. */
export const blumeTheme = (theme: ResolvedTheme, note = header) =>
  [
    `/* ${note} */`,
    `/* ${theme.name}: ${theme.description} */`,
    blumeThemeCss(theme),
  ].join("\n\n") + "\n";

/**
 * Every theme, core and optional, as Blume's tokens, each under
 * `data-gw-docs-theme`, for a site that lets readers pick one with the theme
 * picker. An optional theme with one scheme has rules for that scheme only;
 * the picker keeps the page in it.
 */
export const blumeThemes = (themes: readonly ResolvedTheme[], note = header) =>
  [`/* ${note} */`, blumeThemesCss(themes)].join("\n\n") + "\n";

/**
 * Themes as Blume's tokens, each under `data-gw-docs-theme` set to its id,
 * so the theme picker can offer them.
 */
export const blumeThemesCss = (themes: readonly ResolvedTheme[]) =>
  themes
    .flatMap((theme) =>
      blumeRules(theme, `:root[data-gw-docs-theme="${theme.id}"]`),
    )
    .join("\n\n");

const hexRoles = (roles: Roles) =>
  Object.fromEntries(
    Object.entries(roles).map(([role, color]) => [role, toHex(color)]),
  );

/** A solved theme's roles as hex in each mode it has, as terminals take them. */
export const hexModes = (theme: ResolvedTheme) =>
  Object.fromEntries(
    modes.flatMap((mode) => {
      const roles = theme.modes[mode];

      return roles === undefined ? [] : [[mode, hexRoles(roles)]];
    }),
  );

const data = (themes: readonly ResolvedTheme[]) => ({
  themes: themes.map((theme) => ({
    id: theme.id,
    name: theme.name,
    description: theme.description,
    optional: theme.optional,
    family: theme.family ?? null,
    examples: theme.examples,
    style: theme.style,
    properties: styleProperties(theme.style),
    modes: hexModes(theme),
  })),
});

export const json = (themes: readonly ResolvedTheme[]) =>
  `${JSON.stringify(data(themes), null, 2)}\n`;

export const typescript = (themes: readonly ResolvedTheme[], note = header) =>
  [
    `// ${note}`,
    "",
    `export const themes = ${JSON.stringify(data(themes).themes, null, 2)} as const;`,
    "",
    'export type ThemeId = (typeof themes)[number]["id"];',
    "",
  ].join("\n");

export const qml = (themes: readonly ResolvedTheme[], note = header) =>
  [
    `// ${note}`,
    "pragma Singleton",
    "import QtQuick",
    "",
    "QtObject {",
    `    readonly property var themes: (${JSON.stringify(
      Object.fromEntries(themes.map((theme) => [theme.id, hexModes(theme)])),
    )})`,
    "}",
    "",
  ].join("\n");

/** Resolved colors for OpenTUI, which takes hex strings. */
export const opentui = (themes: readonly ResolvedTheme[], note = header) =>
  [
    `// ${note}`,
    "",
    `export const opentuiThemes = ${JSON.stringify(
      Object.fromEntries(themes.map((theme) => [theme.id, hexModes(theme)])),
      null,
      2,
    )} as const;`,
    "",
  ].join("\n");

/**
 * Plain CLI output follows the terminal: roles map onto the 16 ANSI colors,
 * so the terminal's own theme decides how they look.
 */
export const ansi = (note = header) =>
  `${JSON.stringify(
    {
      $comment: note,
      roles: {
        "text-primary": { name: "default", index: null },
        "text-strong": { name: "default", index: null, bold: true },
        "text-secondary": { name: "brightBlack", index: 8 },
        accent: { name: "cyan", index: 6 },
        info: { name: "blue", index: 4 },
        success: { name: "green", index: 2 },
        important: { name: "magenta", index: 5 },
        warning: { name: "yellow", index: 3 },
        danger: { name: "red", index: 1 },
      },
      noColor: "Plain text when NO_COLOR is set or stdout isn't a terminal.",
    },
    null,
    2,
  )}\n`;

const modeLabel: Record<Mode, string> = {
  light: "Light",
  dark: "Dark",
  darker: "Darker",
};

const roleLabel = (role: string) =>
  statuses.some((status) => status === role) ? `Status: ${role}` : role;

/** The contrast report as a docs page, one table per theme. */
export const contrastPage = (themes: readonly ResolvedTheme[]) => {
  const sections = themes.map((theme) => {
    const results = check(theme);

    const rows = [...new Set(results.map((result) => result.role))].map(
      (role) => {
        const cells = modes.map((mode) => {
          const result = results.find(
            (item: Check) => item.role === role && item.mode === mode,
          );

          return result === undefined
            ? "n/a"
            : `${result.ratio.toFixed(2)}${result.passes ? "" : " ✗"}`;
        });

        const target = results.find((item) => item.role === role)?.target ?? 0;

        return `| ${roleLabel(role)} | ${target} | ${cells.join(" | ")} |`;
      },
    );

    return [
      `## ${theme.name}`,
      "",
      theme.optional
        ? "Optional. Mapped from its own palette, so it's reported rather than held to the targets."
        : "",
      "",
      `| Role | Target | ${modes.map((mode) => modeLabel[mode]).join(" | ")} |`,
      "| --- | --- | --- | --- | --- |",
      ...rows,
    ]
      .filter((line, index, lines) => line !== "" || lines[index - 1] !== "")
      .join("\n");
  });

  return [
    "---",
    "title: Contrast report",
    "description: Every theme role measured against its contrast target on the raised surface, in light, dark and Darker.",
    "---",
    "",
    `<!-- ${header} -->`,
    "",
    "Each role is measured with the WCAG 2 ratio against the raised surface, the lowest-contrast surface text sits on. `mise run check` fails when a core theme misses a target; ✗ marks a miss.",
    "",
    ...sections.flatMap((section) => [section, ""]),
  ].join("\n");
};

const styleSummary = (style: Style) => [
  `| Font | ${style.font}${style.figures === undefined ? "" : `, with ${style.figures} figures`} |`,
  `| Code | ${style.mono} |`,
  `| Radius | Panels ${style.radius.panel}px, controls ${style.radius.control === 999 ? "pill" : `${style.radius.control}px`}, chips ${style.radius.chip === 999 ? "pill" : `${style.radius.chip}px`} |`,
  `| Borders | ${borderLevel(style.border.strength) === 0 ? "None" : `${style.border.width}px, ${style.border.strength}`} |`,
  `| Weights | ${style.weights.regular} and ${style.weights.strong} |`,
  `| Density | ${style.density}${style.rows === "dense" ? ", lists as dense rows" : ""} |`,
  `| Labels | ${style.capitals ? "Capitals" : "Sentence case"} |`,
  `| Links | ${style.link.color === "accent" ? "Accent" : "Strong text"}, ${style.link.underline} underline |`,
  `| Surface accent | ${style.surfaceAccent} |`,
];

/** A docs page for one core theme, rendering it live in every mode. */
export const themePage = (theme: ResolvedTheme) =>
  [
    "---",
    `title: ${theme.name}`,
    `description: ${theme.description}`,
    "---",
    "",
    `{/* ${header} */}`,
    "",
    `<ThemePreview theme="${theme.id}" />`,
    "",
    ...(theme.examples.length === 0
      ? []
      : [
          `Example users: ${theme.examples.join(", ")}. Any app can pick any theme.`,
          "",
        ]),
    "## Style",
    "",
    "| | |",
    "| --- | --- |",
    ...styleSummary(theme.style),
    "",
    "## Roles",
    "",
    `<ThemeSwatches theme="${theme.id}" />`,
    "",
    `The source is [\`packages/tokens/themes/${theme.id}.json\`](https://github.com/timmo001/groundwork/blob/main/packages/tokens/themes/${theme.id}.json).`,
    "",
  ].join("\n");

/** One page for the optional themes, mapped from their own palettes. */
export const optionalPage = (themes: readonly ResolvedTheme[]) => {
  const optional = themes.filter((theme) => theme.optional);
  const families = [...new Set(optional.map((theme) => theme.family ?? ""))];

  return [
    "---",
    "title: Optional themes",
    "description: Catppuccin, Tokyo Night and GitHub, mapped onto the roles so they stay faithful to their palettes. Apps opt in.",
    "---",
    "",
    `{/* ${header} */}`,
    "",
    "Catppuccin's flavors are one mode each, so an app in one stays in its scheme. GitHub's cover both light and dark, and so do Tokyo Night's, each taking Day as its light side. Each is mapped straight onto the roles rather than solved, so it looks the way the palette's authors intended. They take Base's style. The [contrast report](/themes/contrast) shows where a palette sits below the core targets.",
    "",
    ...families.flatMap((family) => [
      `## ${family}`,
      "",
      ...optional
        .filter((theme) => theme.family === family)
        .flatMap((theme) => [
          `### ${theme.name}`,
          "",
          `<ThemePreview theme="${theme.id}" />`,
          "",
        ]),
    ]),
  ].join("\n");
};
